<h2>Каталог</h2><form method="get"><label>Категория <select name="category"><option value="">Все</option><?php foreach ($categories as $c): ?><option value="<?= $c->id ?>" <?= (string)$c->id === $category ? 'selected' : '' ?>><?= e($c->name) ?></option><?php endforeach; ?></select></label><label>Сортировка <select name="sort"><option value="name">По названию</option><option value="price" <?= $sort === 'price' ? 'selected' : '' ?>>По цене</option></select></label><button>Показать</button></form>
<?php if (!$products): ?><p>Товары не найдены.</p><?php endif; ?><?php foreach ($products as $p): ?><article><a href="/product?id=<?= $p->id ?>"><?= e($p->name) ?></a> — <?= number_format($p->price, 2, ',', ' ') ?> ₽<form action="/cart/add" method="post"><input type="hidden" name="product_id" value="<?= $p->id ?>"><input type="hidden" name="qty" value="1"><button>В корзину</button></form></article><?php endforeach; ?>
